// supabase/functions/site/index.ts
// Free public host for the G-Taxi launch site + NFC arrival page, AND the
// public touchpoint resolver (merged to fit the plan's function budget).
//   .../functions/v1/site                    -> serves the HTML site
//   .../functions/v1/site?node=<id>          -> serves the HTML (arrival mode)
//   .../functions/v1/site?resolve=1&node=<id>-> JSON pickup {name,address,lat,lng}
// verify_jwt = false: it's a public website + a public tap resolver.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";

const HTML_B64 = "";
const html = new TextDecoder().decode(Uint8Array.from(atob(HTML_B64), c => c.charCodeAt(0)));

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  const url = new URL(req.url);

  // --- Touchpoint resolver (public, read-only, only a puck's public location) ---
  if (url.searchParams.has("resolve")) {
    const tag = url.searchParams.get("tag") ?? "";
    const node = url.searchParams.get("node") ?? "";
    if (!tag && !node) {
      return new Response(JSON.stringify({ found: false, reason: "no tag or node" }),
        { status: 400, headers: { ...cors, "Content-Type": "application/json" } });
    }
    const supabase = createClient(Deno.env.get("SUPABASE_URL") ?? "", Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "");
    let q = supabase.from("kiosk_nodes")
      .select("id, location_name, pickup_address, lat, lng, is_active, merchant_id").limit(1);
    q = node ? q.eq("id", node) : q.eq("tag_uid", tag);
    const { data } = await q.maybeSingle();
    if (!data || data.is_active === false) {
      return new Response(JSON.stringify({ found: false, reason: "touchpoint not active yet" }),
        { headers: { ...cors, "Content-Type": "application/json" } });
    }
    supabase.from("kiosk_nodes").update({ last_heartbeat: new Date().toISOString() }).eq("id", data.id).then(null, () => null);
    return new Response(JSON.stringify({
      found: true,
      pickup: { name: data.location_name ?? "G-Taxi touchpoint", address: data.pickup_address ?? null, lat: data.lat ?? null, lng: data.lng ?? null },
      is_merchant: !!data.merchant_id,
    }), { headers: { ...cors, "Content-Type": "application/json" } });
  }

  // --- Otherwise: serve the site ---
  return new Response(html, {
    headers: { ...cors, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=300" },
  });
});
